def build():
    originals = json.loads(SOURCE.read_text(encoding="utf-8"))
    if set(TRANSLATIONS) != {record["id"] for record in originals}:
        raise ValueError("Translation entries must cover each original record exactly once")
    candidates = copy.deepcopy(originals)
    next_id = len(originals)
    for record in originals:
        for language in ("fr", "ar"):
            question, answer, keywords, related_questions = TRANSLATIONS[record["id"]][language]
            translated = copy.deepcopy(record)
            translated.update({
                "id": next_id,
                "question": question,
                "answer": answer,
                "keywords": keywords,
                "related_questions": related_questions,
                "language": language,
                "reviewed_at": None,
            })
            candidates.append(translated)
            next_id += 1
    OUTPUT.write_text(json.dumps(candidates, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Wrote {len(candidates)} records ({len(originals)} originals + {len(candidates) - len(originals)} translation candidates)")


if __name__ == "__main__":
    build()
